CREATE TABLE oref_t (id int, x int);
CREATE TABLE oref_u (k int, w int);
INSERT INTO oref_t VALUES (1, 2), (2, 0), (3, 5);
INSERT INTO oref_u VALUES (1, 100), (1, 101), (2, 200), (3, 300), (3, 301), (3, 302);
SELECT id, EXISTS (SELECT 1 FROM (SELECT 10 / t.x) s) FROM oref_t t WHERE x <> 0 ORDER BY id;
SELECT id, (SELECT s.a FROM (SELECT t.id * 10 AS a) s) FROM oref_t t ORDER BY id;
SELECT id, (SELECT count(*) FROM (SELECT * FROM oref_u u WHERE u.k = t.id) s) FROM oref_t t ORDER BY id;
SELECT id, (SELECT sum(w) FROM (SELECT w FROM oref_u u WHERE u.k = t.id ORDER BY w LIMIT 2) s) FROM oref_t t ORDER BY id;
SELECT id, (SELECT max(l.w) FROM oref_u u, LATERAL (SELECT u.w + t.id AS w) l WHERE u.k = t.id) FROM oref_t t ORDER BY id;
SELECT id, (SELECT t.id UNION SELECT t.id + 1 ORDER BY 1 DESC LIMIT 1) AS z FROM oref_t t ORDER BY id;
SELECT id, (SELECT count(*) FROM (SELECT k FROM oref_u u WHERE k = t.id UNION ALL SELECT t.x) s) FROM oref_t t ORDER BY id;
SELECT id, ARRAY(SELECT w FROM oref_u u WHERE u.k = t.id ORDER BY w LIMIT t.id) FROM oref_t t ORDER BY id;
SELECT id, (SELECT count(*) FROM oref_u a JOIN oref_u b ON a.k = b.k AND a.k = t.id) FROM oref_t t ORDER BY id;
SELECT id, (SELECT count(*) FROM oref_u a LEFT JOIN oref_u b ON a.k = b.k + t.id) FROM oref_t t ORDER BY id;
SELECT id, EXISTS (SELECT 1 FROM oref_u u WHERE k = t.id INTERSECT SELECT t.id) FROM oref_t t ORDER BY id;
SELECT id, (SELECT w FROM oref_u u WHERE k = t.id EXCEPT SELECT 100 ORDER BY 1 LIMIT 1) FROM oref_t t ORDER BY id;
SELECT id, (SELECT array_agg(w ORDER BY w) FROM oref_u u WHERE k = t.id OFFSET t.id - 1) FROM oref_t t ORDER BY id;
SELECT id, w FROM oref_t t, LATERAL (SELECT w FROM oref_u u WHERE u.k = t.id ORDER BY w DESC LIMIT 1) s ORDER BY id;
SELECT id, s.c FROM oref_t t, LATERAL (SELECT count(*) c FROM (SELECT * FROM oref_u u WHERE u.k = t.id) z) s ORDER BY id;
SELECT id, s.v FROM oref_t t, LATERAL (SELECT t.id AS v UNION ALL SELECT t.x) s ORDER BY id, v;
SELECT id, s.v FROM oref_t t, LATERAL (SELECT t.id AS v UNION SELECT t.x) s ORDER BY id, v;
SELECT id, (SELECT v FROM (SELECT t.x AS v UNION SELECT 99) s ORDER BY v LIMIT 1) FROM oref_t t ORDER BY id;
SELECT count(*) FROM oref_u u OFFSET 1;
SELECT (SELECT count(*) FROM oref_u u OFFSET 1);
SELECT k, (SELECT count(*) FROM oref_u u2 WHERE u2.k = u.k OFFSET 1) FROM oref_u u ORDER BY 1;
SELECT k, (SELECT count(*) FROM oref_u u2 WHERE u2.k = u.k OFFSET u.k - 1) FROM oref_u u ORDER BY 1;
SELECT k, (SELECT count(*) FROM oref_u u2 WHERE u2.k = u.k LIMIT u.k - 1) FROM oref_u u ORDER BY 1;
SELECT k, (SELECT max(w) FROM oref_u u2 WHERE u2.k = u.k GROUP BY u2.k OFFSET u.k - 1) FROM oref_u u ORDER BY 1;
SELECT (SELECT 1 OFFSET 1), (SELECT 1 LIMIT 0), (SELECT 1/0 LIMIT 0), (SELECT max(1/0) LIMIT 0);
SELECT (SELECT count(*) FROM oref_u u LIMIT -1);
SELECT (SELECT count(*) LIMIT (SELECT 0));
SELECT (SELECT w FROM oref_u u ORDER BY (SELECT 1), w LIMIT (SELECT 1));
SELECT t.id, u.w FROM oref_t t JOIN oref_u u ON (SELECT u.k = t.id) ORDER BY 1, 2;
SELECT t.id, u.w FROM oref_t t JOIN oref_u u ON u.k = t.id AND EXISTS (SELECT 1 FROM oref_u u2 WHERE u2.w > u.w AND u2.k = t.id) ORDER BY 1, 2;
SELECT t.id, u.w FROM oref_t t LEFT JOIN oref_u u ON u.k IN (SELECT t.id) ORDER BY 1, 2;
SELECT t.id, u.w FROM oref_t t JOIN oref_u u ON u.k = t.id AND u.w = (SELECT max(w) FROM oref_u u3 WHERE u3.k = t.id) ORDER BY 1, 2;
SELECT id, (SELECT count(*) FROM oref_u a JOIN oref_u b ON a.k = b.k AND (SELECT a.w > t.id * 100)) FROM oref_t t ORDER BY 1;
SELECT t.id, u.w FROM oref_t t JOIN oref_u u ON (SELECT 1) = 1 AND u.k = t.id ORDER BY 1, 2;
SELECT t.id, s.n FROM oref_t t LEFT JOIN LATERAL (SELECT count(*) AS n FROM oref_u u WHERE u.k = t.id) s ON s.n > (SELECT min(k) FROM oref_u) ORDER BY 1;
SELECT t.id FROM oref_t t FULL JOIN oref_u u ON u.k = t.id AND (SELECT u.w < 300) ORDER BY 1, u.w;
SELECT id, id IN (SELECT t.x UNION SELECT 1) FROM oref_t t ORDER BY id;
SELECT id, id = ANY (SELECT t.x + 1 UNION ALL SELECT 3) FROM oref_t t ORDER BY id;
SELECT id, (id, x) IN (SELECT t.id, t.x UNION SELECT 0, 0) FROM oref_t t ORDER BY id;
SELECT id, 'a' IN (SELECT t.id::text UNION SELECT 'a' COLLATE "C") FROM oref_t t ORDER BY id;
SELECT (SELECT s.m FROM (SELECT max(t.id) AS m) s) FROM oref_t t;
SELECT (SELECT max(t.id) UNION ALL SELECT 0 ORDER BY 1 DESC LIMIT 1) FROM oref_t t;
SELECT x, (SELECT s.m FROM (SELECT sum(t.id) AS m) s) FROM oref_t t GROUP BY x ORDER BY x;
SELECT (SELECT s.m FROM LATERAL (SELECT max(t.id) AS m) s) FROM oref_t t;
